<?php
declare(strict_types=1);
require_once __DIR__.'/../config/database.php';
if (session_status() !== PHP_SESSION_ACTIVE) { session_start(); }
function e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES|ENT_SUBSTITUTE, 'UTF-8'); }
function csrf(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function verify_csrf(): void { if($_SERVER['REQUEST_METHOD']==='POST' && !hash_equals($_SESSION['csrf']??'', $_POST['csrf']??'')){ http_response_code(400); exit('Invalid form token. Please go back and try again.'); } }
function flash(string $type,string $message): void { $_SESSION['flash']=[$type,$message]; }
function go(string $url): never { header('Location: '.$url); exit; }
function current_user(): ?array { if(empty($_SESSION['uid'])) return null; $q=db()->prepare('SELECT u.id,u.name,u.email,u.role,u.status,p.college,p.course,p.semester,p.avatar FROM users u LEFT JOIN student_profiles p ON p.user_id=u.id WHERE u.id=?'); $q->execute([$_SESSION['uid']]); return $q->fetch() ?: null; }
function require_login(): array { $u=current_user(); if(!$u || $u['status']!=='active') go('../login.php'); return $u; }
function require_admin(): array { $u=current_user(); if(!$u || $u['role']!=='admin') { http_response_code(403); exit('Access denied. <a href="../login.php">Login</a>'); } return $u; }
function notify(int $to,string $text,string $link=''): void { db()->prepare('INSERT INTO notifications(user_id,message,link) VALUES(?,?,?)')->execute([$to,$text,$link]); }
function tag(string $text): string { return '<span class="tag">'.e($text).'</span>'; }
function rating_avg(int $id): string { $q=db()->prepare('SELECT AVG(rating) FROM ratings WHERE ratee_id=?');$q->execute([$id]);$v=$q->fetchColumn();return $v?number_format((float)$v,1):'New'; }
function completion(array $p): int { $fields=['about','learning_goals','study_mode','availability_days','languages'];$n=0;foreach($fields as $f)if(!empty($p[$f]))$n++;return (int)round($n/count($fields)*100); }
function match_info(int $me,int $them): array {
 $a=db()->prepare('SELECT * FROM student_profiles WHERE user_id=?');$a->execute([$me]);$p=$a->fetch()?:[];$b=db()->prepare('SELECT * FROM student_profiles WHERE user_id=?');$b->execute([$them]);$q=$b->fetch()?:[];
 $score=0;$why=[];
 $shared=db()->prepare("SELECT COUNT(*) FROM user_subjects a JOIN user_subjects b ON a.subject_id=b.subject_id WHERE a.user_id=? AND b.user_id=?");$shared->execute([$me,$them]);if($shared->fetchColumn()>0){$score+=25;$why[]='Shared subject interests';}
 $compat=db()->prepare("SELECT COUNT(*) FROM user_subjects a JOIN user_subjects b ON a.subject_id=b.subject_id WHERE a.user_id=? AND b.user_id=? AND a.intent='want' AND b.intent='help'");$compat->execute([$me,$them]);$compatN=(int)$compat->fetchColumn();$compat->execute([$them,$me]);$compatN+=(int)$compat->fetchColumn();if($compatN){$score+=20;$why[]='Learning and teaching goals align';}
 $skills=db()->prepare('SELECT COUNT(*) FROM user_skills a JOIN user_skills b ON a.skill_id=b.skill_id WHERE a.user_id=? AND b.user_id=?');$skills->execute([$me,$them]);if($skills->fetchColumn()){ $score+=20;$why[]='Skills in common'; }
 if(!empty($p['study_mode']) && !empty($q['study_mode']) && ($p['study_mode']===$q['study_mode']||$p['study_mode']==='Both'||$q['study_mode']==='Both')){$score+=15;$why[]='Compatible study mode';}
 if(!empty($p['availability_days'])&&!empty($q['availability_days'])&&array_intersect(explode(',',$p['availability_days']),explode(',',$q['availability_days']))){$score+=10;$why[]='Overlapping availability';}
 if(!empty($p['course'])&&$p['course']===$q['course']){$score+=5;$why[]='Same course';} if(!empty($p['semester'])&&$p['semester']===$q['semester']){$score+=5;$why[]='Same semester';}
 return ['score'=>min(100,$score),'why'=>$why];
}
function page_start(string $title,bool $admin=false): void { $u=current_user(); $flash=$_SESSION['flash']??null;unset($_SESSION['flash']); echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'.e($title).' · StudySync</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="'.(str_contains($_SERVER['PHP_SELF'],'/student/')||str_contains($_SERVER['PHP_SELF'],'/admin/')?'../':'').'assets/css/style.css" rel="stylesheet"></head><body><nav class="navbar navbar-expand-lg bg-white border-bottom sticky-top"><div class="container"><a class="navbar-brand fw-bold" href="'.(str_contains($_SERVER['PHP_SELF'],'/student/')?'dashboard.php':'index.php').'"><span class="brand-icon"><i class="bi bi-mortarboard-fill"></i></span> StudySync</a><button class="navbar-toggler" data-bs-toggle="collapse" data-bs-target="#nav"><span class="navbar-toggler-icon"></span></button><div id="nav" class="collapse navbar-collapse"><div class="navbar-nav ms-auto align-items-lg-center">'; if($u){$base=$admin?'../admin/':'../student/';$items=$admin?['Dashboard'=>'dashboard.php','Students'=>'students.php','Subjects'=>'catalog.php?type=subject','Skills'=>'catalog.php?type=skill','Groups'=>'groups.php','Reports'=>'reports.php','Feedback'=>'feedback.php']:['Dashboard'=>'dashboard.php','My Profile'=>'profile.php','Find Partners'=>'find-partners.php','Requests'=>'requests.php','Messages'=>'messages.php','Study Groups'=>'groups.php','Sessions'=>'sessions.php','Notifications'=>'notifications.php','Settings'=>'settings.php']; foreach($items as $n=>$url)echo '<a class="nav-link" href="'.$base.$url.'">'.e($n).'</a>';echo '<a class="btn btn-sm btn-outline-primary ms-lg-2" href="'.($admin?'../':'').'logout.php">Sign out</a>'; } else echo '<a class="nav-link" href="'.(str_contains($_SERVER['PHP_SELF'],'about.php')?'../':'').'index.php#how">How it works</a><a class="nav-link" href="'.(str_contains($_SERVER['PHP_SELF'],'about.php')?'about.php':'about.php').'"><span>About</span></a><a class="nav-link" href="'.(str_contains($_SERVER['PHP_SELF'],'about.php')?'../':'').'login.php">Login</a><a class="btn btn-primary ms-lg-2" href="'.(str_contains($_SERVER['PHP_SELF'],'about.php')?'../':'').'register.php">Get started</a>';echo '</div></div></div></nav><main class="container py-4">';if($flash)echo '<div class="alert alert-'.e($flash[0]).' alert-dismissible">'.e($flash[1]).'<button class="btn-close" data-bs-dismiss="alert"></button></div>'; if($u)echo '<div class="d-flex align-items-center justify-content-between mb-4"><div><div class="eyebrow">'.($admin?'ADMIN CONSOLE':'YOUR LEARNING SPACE').'</div><h1 class="h3 mb-0">'.e($title).'</h1></div><div class="small text-secondary">'.e($u['name']).'</div></div>'; }
function page_end(): void { echo '</main><footer class="footer py-4 mt-5"><div class="container d-flex justify-content-between"><span>© '.date('Y').' StudySync</span><span>Find the right study partner. Learn better together.</span></div></footer><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="'.(str_contains($_SERVER['PHP_SELF'],'/student/')||str_contains($_SERVER['PHP_SELF'],'/admin/')?'../':'').'assets/js/main.js"></script></body></html>'; }
function get_user_tags(int $uid,string $kind): array { if($kind==='skills'){$sql='SELECT s.name FROM user_skills x JOIN skills s ON x.skill_id=s.id WHERE x.user_id=?';}else{$sql='SELECT s.name FROM user_subjects x JOIN subjects s ON x.subject_id=s.id WHERE x.user_id=? AND x.intent=?';} $q=db()->prepare($sql);$q->execute($kind==='skills'?[$uid]:[$uid,'help']);return array_column($q->fetchAll(),'name'); }
